contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking inputs: whether caller is admin and a description
    function run(bool makeAdmin, string calldata description) public payable {
        // set up admin status: onlyAdmin checks isAdmin[msg.sender], where msg.sender will be this contract
        // we can call c.isAdmin(address) getter is public, but mapping has getter isAdmin
        // We need to make this contract an admin if requested. The only way to change c.isAdmin is external; but C as given has no function to set isAdmin.
        // However per constraints, the checker deploys a fresh c and then calls run; we cannot modify c.isAdmin unless it's already set.
        // So precondition: if makeAdmin is true, require that this contract is already an admin according to c.isAdmin(address(this)).
        if (makeAdmin) {
            require(c.isAdmin(address(this)), "precondition: must be admin to exercise success branch");
        }

        // Record balance of c and owner getter on any existing oracle cannot be read; but after calling newEmergencyOracle
        // it will deploy EmergencyOracle and emit event. We cannot directly capture events here; instead we can observe that
        // call should succeed (not revert) when makeAdmin true, and revert when not admin.

        bool reverted;
        try c.newEmergencyOracle(description) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: call reverts iff caller is not admin. That is, reverted == !c.isAdmin(address(this))
        // We must read c.isAdmin(address(this)) (public getter) and assert the relation.
        assert(reverted == (!c.isAdmin(address(this))));
    }

    receive() external payable { }
}

