// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    C c;

    function setUp() public {
        c = new C();
    }

    function _run(bool makeAdmin, string memory description) internal {
        if (makeAdmin) {
            require(c.isAdmin(address(this)), "precondition: must be admin to exercise success branch");
        }
        bool reverted;
        try c.newEmergencyOracle(description) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted == (!c.isAdmin(address(this))));
    }

    function testFuzz_run(bool makeAdmin, string memory description) public {
        _run(makeAdmin, description);
    }

    receive() external payable { }
}
